                }
            runBlocking { replayApi.call(RotatingOAuthAuthenticator()) }
            assertEquals(listOf("on", "on"), replayed.sentHeaders.map { it["X-Hook"] })

            val (transport, seen) = retryingClient(503, 200)
            runBlocking { HookedApi(transport, RecordingHook { it["X-Hook"] = "on" }).call() }
            assertEquals(2, seen.size)
            assertEquals(listOf("on", "on"), seen.map { it.headers["X-Hook"] })
        }

        @Test
        @DisplayName("bhvHooks007 the fresh authentication headers of a replay still replace a hook header of the same name")
        fun aReplayKeepsItsFreshAuthentication() {
            val client = ScriptedApiClient(listOf(401, 200))
            val api =
                object : com.example.petstore.api.BaseApi(
                    client,
                    Configuration
                        .builder()
                        .baseUrl("http://localhost")
                        .callHook(RecordingHook { it["authorization"] = "Bearer hook" })
                        .build(),
                ) {
                    suspend fun call(auth: Authenticator) =
                        invokeApi(
                            "GET",
                            "/items",
                            mutableMapOf(),
                            mutableMapOf(),
                            null,
                            arrayOf("application/json"),
                            "application/json",
                            auth,
                        )
                }
            runBlocking { api.call(RotatingOAuthAuthenticator()) }
            assertEquals("Bearer hook", client.sentHeaders[0]["authorization"])
            assertEquals("Bearer t2", client.sentHeaders[1]["Authorization"])
            assertNull(client.sentHeaders[1]["authorization"])
        }

        @Test
        @DisplayName("bhvHooks008 a call that is retried by the transport calls start once and finish once")
        fun aRetriedCallStartsAndFinishesOnce() {
            val (transport, seen) = retryingClient(503, 503, 200)
            val hook = RecordingHook()
            runBlocking { HookedApi(transport, hook).call() }
            assertEquals(3, seen.size)
            assertEquals(1, hook.infos.size)
            assertEquals(200, hook.outcomes.single().statusCode)
        }

        @Test
        @DisplayName("bhvHooks009 the plain and the WithHttpInfo variant of an operation call the hook once each")
        fun bothVariantsCallTheHookOnce() {
            val hook = RecordingHook()
            val client = BodyApiClient(200, "{\"name\":\"n\",\"photoUrls\":[]}")
            val api =
                com.example.petstore.api.PetApi(
                    client,
                    Configuration
                        .builder()
                        .baseUrl("http://localhost:8080")
                        .callHook(hook)
                        .build(),
                )
            runBlocking { api.getPetById(7L) }
            assertEquals(1, hook.infos.size)
            runBlocking { api.getPetByIdWithHttpInfo(7L) }
            assertEquals(2, hook.infos.size)
            assertEquals(2, hook.outcomes.size)
        }

        @Test
        @DisplayName("bhvHooks011 finish gets the status, the lower-cased response headers and no error on a 2xx")
        fun finishGetsTheSuccess() {
            val hook = RecordingHook()
            runBlocking { HookedApi(BodyApiClient(200, "{}"), hook).call() }
            val outcome = hook.outcomes.single()
            assertEquals(200, outcome.statusCode)
            assertEquals(mapOf("content-type" to "application/json", "x-reply" to "yes"), outcome.headers)
            assertNull(outcome.error)
        }

        @Test
        @DisplayName("bhvHooks012 finish gets the status, the headers and the same typed ApiException the caller receives on a non-2xx")
        fun finishGetsTheTypedError() {
            val hook = RecordingHook()
            val thrown =
                assertThrows(NotFoundException::class.java) {
                    runBlocking { HookedApi(BodyApiClient(404, "{}"), hook).call() }
                }
            val outcome = hook.outcomes.single()
            assertEquals(404, outcome.statusCode)
            assertEquals("yes", outcome.headers!!["x-reply"])
            assertSame(thrown, outcome.error)
        }

        @Test
        @DisplayName("bhvHooks013 finish gets status 0, null headers and the network error when no response arrived")
        fun finishGetsTheNetworkError() {
            val hook = RecordingHook()
            val failure = NetworkException("down", java.io.IOException("refused"))
            val thrown =
                assertThrows(NetworkException::class.java) {
                    runBlocking { HookedApi(FailingApiClient(failure), hook).call() }
                }
            val outcome = hook.outcomes.single()
            assertEquals(0, outcome.statusCode)
            assertNull(outcome.headers)
            assertSame(thrown, outcome.error)
        }

        @Test
        @DisplayName("bhvHooks014 finish gets the timeout error when the end-to-end budget is exhausted, never the cancellation error")
        fun finishGetsTheTimeout() {
            val engine =
                MockEngine {
                    kotlinx.coroutines.delay(10_000)
                    respond("{}")
                }
            val http =
                HttpClient(engine) {
                    followRedirects = false
                    install(io.ktor.client.plugins.HttpTimeout)
                }
            val hook = RecordingHook()
            val thrown =
                assertThrows(NetworkTimeoutException::class.java) {
                    runBlocking { HookedApi(DefaultApiClient(http), hook).call(callTimeout = 100) }
                }
            val outcome = hook.outcomes.single()
            assertSame(thrown, outcome.error)
            assertFalse(outcome.error is kotlin.coroutines.cancellation.CancellationException)
        }

        @Test
        @DisplayName("bhvHooks015 finish gets the cancellation and the call rethrows it, never as the timeout error")
        fun finishGetsTheCancellation() {
            val hook = RecordingHook()
            val hung =
                object : ApiClient {
                    val started = kotlinx.coroutines.CompletableDeferred<Unit>()

                    override suspend fun sendRequest(
                        method: String,
                        url: String,
                        headers: Map<String, String>,
                        body: Any?,
                        noRedirect: Boolean,
                    ): ApiHttpResponse {
                        started.complete(Unit)
                        kotlinx.coroutines.awaitCancellation()
                    }
                }
            var thrown: Throwable? = null
            runBlocking {
                val job =
                    launch {
                        try {
                            HookedApi(hung, hook).call()
                        } catch (e: Throwable) {
                            thrown = e
                            throw e
                        }
                    }
                hung.started.await()
                job.cancelAndJoin()
            }
            assertTrue(thrown is kotlin.coroutines.cancellation.CancellationException)
            assertSame(thrown, hook.outcomes.single().error)
            assertEquals(0, hook.outcomes.single().statusCode)
        }

        @Test
        @DisplayName(
            "bhvHooks016 finish gets the SerializationException, with the status that arrived, when the response cannot be decoded",
        )
        fun finishGetsTheDecodeError() {
            val hook = RecordingHook()
            val thrown =
                assertThrows(SerializationException::class.java) {
                    runBlocking { HookedApi(BodyApiClient(200, "{nope"), hook).callForResult<com.example.petstore.models.Category>() }
                }
            val outcome = hook.outcomes.single()
            assertEquals(200, outcome.statusCode)
            assertEquals("yes", outcome.headers!!["x-reply"])
            assertSame(thrown, outcome.error)
        }

        @Test
        @DisplayName("bhvHooks017 finish is called when the request body cannot be encoded and nothing is sent")
        fun finishIsCalledWhenTheBodyCannotBeEncoded() {
            val client = CapturingApiClient()
            val hook = RecordingHook()
            val thrown =
                assertThrows(SerializationException::class.java) {
                    runBlocking {
                        HookedApi(client, hook).call(
                            body = mapOf("field" to mapOf("nested" to "x")),
                            contentType = "application/x-www-form-urlencoded",
                        )
                    }
                }
            assertEquals("", client.capturedUrl)
            assertEquals(1, hook.infos.size)
            assertSame(thrown, hook.outcomes.single().error)
            assertEquals(0, hook.outcomes.single().statusCode)
        }

        @Test
        @DisplayName("bhvHooks018 an error thrown by start reaches the caller unchanged, nothing is sent and finish is not called")
        fun aThrowingStartPropagates() {
            val client = CapturingApiClient()
            val failure = IllegalStateException("refused")
            val hook =
                CallHook { _, _ ->
                    throw failure
                }
            val thrown =
                assertThrows(IllegalStateException::class.java) {
                    runBlocking { HookedApi(client, hook).call() }
                }
            assertSame(failure, thrown)
            assertEquals("", client.capturedUrl)
        }

        @Test
        @DisplayName("bhvHooks019 an error thrown by finish is swallowed and the caller still gets its result or its own error")
        fun aThrowingFinishIsSwallowed() {
            val hook = CallHook { _, _ -> CallObserver { throw IllegalStateException("observer") } }
            val response = runBlocking { HookedApi(BodyApiClient(200, "{}"), hook).call() }
            assertEquals(200, response.statusCode)
            assertThrows(NotFoundException::class.java) {
                runBlocking { HookedApi(BodyApiClient(404, "{}"), hook).call() }
            }
        }

        @Test
        @DisplayName("bhvHooks021 the url given to the hook never carries the query string or the fragment")
        fun theUrlHasNoQueryOrFragment() {
            val hook = RecordingHook()
            runBlocking {
                HookedApi(CapturingApiClient(), hook).call(
                    path = "/items/7#frag",
                    queryParams = mutableMapOf("a" to "1"),
                )
            }
            assertEquals("http://localhost:8080/items/7", hook.infos.single().url)
        }
    }
